        for (auto &x : row) scanf("%lld", &x);
    const long long INF = LLONG_MAX / 4;
    vector<long long> best(1 << n, INF);
    best[0] = 0;
    for (int mask = 0; mask < (1 << n) - 1; mask++) {
        if (best[mask] == INF) continue;
        int person = __builtin_popcount(mask);          // the next person to be given a job
        for (int job = 0; job < n; job++)
            if (!(mask >> job & 1))
                best[mask | 1 << job] = min(best[mask | 1 << job], best[mask] + cost[person][job]);
    }
    printf("%lld\n", best[(1 << n) - 1]);
}

