#include <bits/stdc++.h>
using namespace std;

const long long M = 998244353;

long long power(long long b, long long e) {
    long long r = 1;
    for (b %= M; e > 0; e >>= 1, b = b * b % M)
        if (e & 1) r = r * b % M;
    return r;
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    long long inv = power(k, M - 2);
    vector<long long> E(n + 2, 0), S(n + 2, 0);         // S[i] = E[i] + E[i+1] + ... (zero from n on)
    for (int i = n - 1; i >= 0; i--) {
        long long hi = (long long)i + k + 1;
        long long window = (S[i + 1] - (hi < n ? S[hi] : 0) + M) % M;
        E[i] = (1 + window * inv) % M;
        S[i] = (S[i + 1] + E[i]) % M;
    }
    printf("%lld\n", E[0]);
}

