const long long M = 1000000007;
typedef array<array<long long, 2>, 2> Mat;

Mat mul(const Mat &A, const Mat &B) {
    Mat C{};
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            for (int t = 0; t < 2; t++) C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % M;
    return C;
}

int main() {
    long long n, k;
    scanf("%lld %lld", &n, &k);
    long long c = (k - 1) % M;
    Mat step = {{{c, c}, {1, 0}}};                       // (diff, same) -> ((k-1)(diff+same), diff)
    Mat result = {{{1, 0}, {0, 1}}};
    for (long long e = n - 1; e > 0; e >>= 1, step = mul(step, step))
        if (e & 1) result = mul(result, step);
    long long diff = result[0][0] * (k % M) % M, same = result[1][0] * (k % M) % M;   // applied to the start (k, 0)
    printf("%lld\n", (diff + same) % M);
}

