int main() {
    string s;
    cin >> s;
    string t = "#";                                    // a#b#a: every palindrome now has a centre on a position
    for (char ch : s) { t += ch; t += '#'; }
    int m = t.size(), centre = 0, right = 0, best = 0;
    vector<int> rad(m, 0);
    for (int i = 0; i < m; i++) {
        int k = i < right ? min(rad[2 * centre - i], right - i) : 0;   // copied from the mirror image, cut at the border
        while (i - k - 1 >= 0 && i + k + 1 < m && t[i - k - 1] == t[i + k + 1]) k++;
        rad[i] = k;
        if (i + k > right) { centre = i; right = i + k; }
        best = max(best, k);                           // a radius in t is a length in s
    }
    printf("%d\n", best);
}

