using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<int> colour(n + 1);
    for (int v = 1; v <= n; v++) scanf("%d", &colour[v]);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> parent(n + 1, 0), order = {1}, answer(n + 1);
    for (size_t i = 0; i < order.size(); i++)
        for (int u : adj[order[i]])
            if (u != parent[order[i]]) { parent[u] = order[i]; order.push_back(u); }
    vector<set<int>> bag(n + 1);
    for (int i = n - 1; i >= 0; i--) {                  // children before parents
        int v = order[i], p = parent[v];
        bag[v].insert(colour[v]);
        answer[v] = bag[v].size();
        if (p == 0) continue;
        if (bag[p].size() < bag[v].size()) swap(bag[p], bag[v]);   // keep the larger, no copying
        for (int c : bag[v]) bag[p].insert(c);          // each element moves at most log n times
        bag[v].clear();
    }
    for (int v = 1; v <= n; v++) printf("%d%c", answer[v], v == n ? '\n' : ' ');
}

