#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    // event: x, kind (0 = a horizontal starts, 1 = a vertical asks, 2 = a horizontal ends), two numbers
    vector<array<long long, 4>> events;
    vector<long long> ys;
    for (int i = 0; i < n; i++) {
        char kind;
        long long c, lo, hi;
        scanf(" %c %lld %lld %lld", &kind, &c, &lo, &hi);
        if (kind == 'H') {
            events.push_back({lo, 0, c, 0});
            events.push_back({hi, 2, c, 0});
            ys.push_back(c);
        } else events.push_back({c, 1, lo, hi});
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    int m = ys.size();
    vector<int> tree(m + 1, 0);
    auto add = [&](int i, int d) { for (; i <= m; i += i & -i) tree[i] += d; };
    auto pre = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; };
    sort(events.begin(), events.end());                 // at equal x: starts, then questions, then ends
    long long total = 0;
    for (auto &e : events) {
        if (e[1] == 1) {
            int hi = upper_bound(ys.begin(), ys.end(), e[3]) - ys.begin();
            int lo = lower_bound(ys.begin(), ys.end(), e[2]) - ys.begin();
            total += pre(hi) - pre(lo);
        } else {
            int at = lower_bound(ys.begin(), ys.end(), e[2]) - ys.begin() + 1;
            add(at, e[1] == 0 ? 1 : -1);
        }
    }
    printf("%lld\n", total);
}

