#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    vector<long long> rem = {0};                        // the empty prefix
    long long p = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        p = ((p + x) % k + k) % k;                      // keep the remainder in 0..k-1 for negative numbers too
        rem.push_back(p);
    }
    sort(rem.begin(), rem.end());                       // equal remainders are now neighbours
    long long total = 0;
    for (size_t i = 0, j; i < rem.size(); i = j) {
        for (j = i; j < rem.size() && rem[j] == rem[i]; j++);
        long long c = j - i;
        total += c * (c - 1) / 2;                       // every pair of equal prefixes is one stretch
    }
    printf("%lld\n", total);
}

