    cin >> a >> b;
    int n = a.size(), m = b.size();
    // len[i][j]: the answer for a from position i on and b from position j on
    vector<vector<unsigned short>> len(n + 1, vector<unsigned short>(m + 1, 0));
    for (int i = n - 1; i >= 0; i--)
        for (int j = m - 1; j >= 0; j--)
            len[i][j] = a[i] == b[j] ? len[i + 1][j + 1] + 1 : max(len[i + 1][j], len[i][j + 1]);
    string out;
    for (int i = 0, j = 0; i < n && j < m;) {           // walk forward, always towards a cell that keeps the best value
        if (a[i] == b[j]) { out += a[i]; i++; j++; }
        else if (len[i + 1][j] >= len[i][j + 1]) i++;
        else j++;
    }
    printf("%d\n%s\n", (int)out.size(), out.c_str());
}

