int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    vector<int> p(n + 1), where(n + 1);
    for (int i = 1; i <= n; i++) scanf("%d", &p[i]);
    vector<bool> seen(n + 1, false);
    for (int s = 1; s <= n; s++) {
        if (seen[s]) continue;
        vector<int> loop;                           // the seats of this loop, in walking order
        for (int x = s; !seen[x]; x = p[x]) { seen[x] = true; loop.push_back(x); }
        int len = loop.size();
        int shift = k % len;                        // only the remainder matters
        for (int j = 0; j < len; j++) where[loop[j]] = loop[(j + shift) % len];
    }
    for (int i = 1; i <= n; i++) printf("%d%c", where[i], i == n ? '\n' : ' ');
}

